<template>
  <ion-page>
    <ion-content :fullscreen="true" class="host-content">
      <header class="host-header">
        <a class="brand" href="/home" aria-label="Casa home"><img src="/casa-logo.png" alt="" class="brand-mark" /><span>casa<span class="brand-dot">.</span></span></a>
        <nav class="host-nav" aria-label="Host navigation"><a href="/host">Dashboard</a><a href="/host/spaces">My spaces</a><a class="active" href="/host/requests">Requests <span class="nav-count">2</span></a></nav>
        <div class="host-account"><span class="avatar">JM</span><span class="host-name">Jamie M.</span><a href="/home">Log out</a></div>
      </header>
      <main class="host-shell">
        <div class="page-heading"><div><a class="back-link" href="/host">← Dashboard</a><span class="eyebrow">BOOKING INBOX</span><h1>Requests.</h1><p>Review potential residents and find the right fit for your spaces.</p></div><span class="pending-summary"><strong>{{ pendingCount }}</strong> pending review</span></div>
        <div class="request-toolbar"><div class="tabs" role="tablist"><button v-for="tab in tabs" :key="tab.value" :class="{ active: selectedTab === tab.value }" type="button" role="tab" :aria-selected="selectedTab === tab.value" @click="selectedTab = tab.value">{{ tab.label }} <span v-if="tab.count">{{ tab.count }}</span></button></div><select v-model="spaceFilter" aria-label="Filter requests by space"><option value="all">All spaces</option><option value="Sage House">Sage House</option><option value="The Greenhouse">The Greenhouse</option></select></div>
        <p v-if="notice" class="notice" role="status">{{ notice }}</p>
        <section class="request-list" aria-label="Booking requests">
          <article v-for="request in filteredRequests" :key="request.name" class="request-card">
            <div class="request-top"><span class="request-avatar">{{ request.initials }}</span><div class="request-person"><h2>{{ request.name }}</h2><span>Requested {{ request.requested }}</span></div><span :class="['request-status', request.status]">{{ request.status === 'pending' ? 'Pending review' : request.status === 'approved' ? 'Approved' : 'Declined' }}</span></div>
            <div class="request-info"><div><small>Interested in</small><strong>{{ request.space }}</strong></div><div><small>Move-in date</small><strong>{{ request.moveIn }}</strong></div><div><small>Monthly rent</small><strong>₱{{ request.price.toLocaleString() }}</strong></div></div>
            <p class="message">“{{ request.message }}”</p>
            <div v-if="request.status === 'pending'" class="request-actions"><button class="approve" type="button" @click="updateRequest(request, 'approved')"><ion-icon :icon="checkmarkOutline" /> Approve request</button><button class="decline" type="button" @click="updateRequest(request, 'declined')">Decline</button><button class="view-profile" type="button" @click="showNotice('Profile details will be available soon.')">View profile</button></div><div v-else class="resolved-note"><ion-icon :icon="checkmarkOutline" /> This request was {{ request.status }}.</div>
          </article>
        </section>
        <div v-if="filteredRequests.length === 0" class="empty-state"><ion-icon :icon="checkmarkOutline" /><h2>No requests here</h2><p>Try another filter to see more booking activity.</p></div>
      </main>
    </ion-content>
  </ion-page>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue';
import { IonContent, IonIcon, IonPage } from '@ionic/vue';
import { checkmarkOutline } from 'ionicons/icons';

type RequestStatus = 'pending' | 'approved' | 'declined';
type BookingRequest = { name: string; initials: string; requested: string; space: string; moveIn: string; price: number; message: string; status: RequestStatus };
const selectedTab = ref('all');
const spaceFilter = ref('all');
const notice = ref('');
const requests = ref<BookingRequest[]>([
  { name: 'Alex Reyes', initials: 'AR', requested: '2 hours ago', space: 'Bed 03 · Sage House', moveIn: 'Nov 01, 2026', price: 7200, message: 'I am a graduate student at Poblacion and keep a quiet, tidy home. I would love to learn more about the community.', status: 'pending' },
  { name: 'Mika Santos', initials: 'MS', requested: 'Yesterday', space: 'Private bed · The Greenhouse', moveIn: 'Nov 15, 2026', price: 8500, message: 'The location is perfect for my work. I am hoping to find a warm and respectful place to stay.', status: 'pending' },
  { name: 'Rafa Cruz', initials: 'RC', requested: 'Oct 18, 2026', space: 'Bed 01 · Sage House', moveIn: 'Nov 01, 2026', price: 7200, message: 'I am relocating to Makati for work and can provide references from my previous landlord.', status: 'approved' },
]);
const tabs = computed(() => [{ label: 'All requests', value: 'all', count: requests.value.length }, { label: 'Pending', value: 'pending', count: pendingCount.value }, { label: 'Resolved', value: 'resolved', count: requests.value.filter((request) => request.status !== 'pending').length }]);
const pendingCount = computed(() => requests.value.filter((request) => request.status === 'pending').length);
const filteredRequests = computed(() => requests.value.filter((request) => (selectedTab.value === 'all' || (selectedTab.value === 'resolved' ? request.status !== 'pending' : request.status === selectedTab.value)) && (spaceFilter.value === 'all' || request.space.includes(spaceFilter.value))));
let noticeTimer: number | undefined;
function showNotice(message: string) { notice.value = message; window.clearTimeout(noticeTimer); noticeTimer = window.setTimeout(() => { notice.value = ''; }, 2500); }
function updateRequest(request: BookingRequest, status: RequestStatus) { request.status = status; showNotice(`${request.name}'s request has been ${status}.`); }
</script>

